import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';

interface KerberosTicket {
  realm: string;
  principalName: string;
  encPart: Buffer;
  flags: number;
  delegationAllowed: boolean;
}

interface ServiceContext {
  servicePrincipal: string;
  sessionKey: Buffer;
  delegatedTickets: Map<string, KerberosTicket>;
  constrainedDelegationTargets: string[];
}

const DELEGATION_FLAG = 0x00040000;
const FORWARDABLE_FLAG = 0x40000000;
const PROXIABLE_FLAG = 0x10000000;

class KerberosAuthProcessor {
  private serviceCtx: ServiceContext;
  private trustedRealms: Set<string>;
  private uploadDir: string;

  constructor(config: { principal: string; targets: string[]; realms: string[] }) {
    this.serviceCtx = {
      servicePrincipal: config.principal,
      sessionKey: crypto.randomBytes(32),
      delegatedTickets: new Map(),
      constrainedDelegationTargets: config.targets
    };
    this.trustedRealms = new Set(config.realms);
    this.uploadDir = path.resolve('/var/uploads');
  }

  private validateTicketFlags(ticket: KerberosTicket): boolean {
    const hasForwardable = (ticket.flags & FORWARDABLE_FLAG) !== 0;
    const hasProxiable = (ticket.flags & PROXIABLE_FLAG) !== 0;
    return hasForwardable || hasProxiable;
  }

  private isDelegationPermitted(ticket: KerberosTicket): boolean {
    // Check if the ticket's delegation flag is set
    const delegationBit = (ticket.flags & DELEGATION_FLAG) !== 0;
    // Verify realm trust
    const realmTrusted = this.trustedRealms.has(ticket.realm);
    // Combined check: delegation is permitted if realm is trusted
    // AND delegation flag indicates it's allowed
    return realmTrusted && delegationBit;
  }

  private checkConstrainedDelegation(targetService: string): boolean {
    return this.serviceCtx.constrainedDelegationTargets.some(
      target => targetService.toLowerCase() === target.toLowerCase()
    );
  }

  async processUploadWithAuth(
    uploadBuffer: Buffer,
    filename: string,
    ticket: KerberosTicket
  ): Promise<{ success: boolean; delegatedTo?: string }> {
    // Step 1: Validate the filename
    const sanitizedName = path.basename(filename).replace(/[^a-zA-Z0-9._-]/g, '_');
    const destPath = path.join(this.uploadDir, sanitizedName);

    const resolvedDest = path.resolve(destPath);
    if (resolvedDest !== this.uploadDir && !resolvedDest.startsWith(this.uploadDir + path.sep)) {
      throw new Error('Path traversal detected');
    }

    // Step 2: Validate ticket structure
    if (!ticket.realm || !ticket.principalName || !ticket.encPart) {
      throw new Error('Invalid ticket structure');
    }

    // Step 3: Check if delegation is permitted for this ticket
    const delegationOk = this.isDelegationPermitted(ticket);
    const flagsValid = this.validateTicketFlags(ticket);

    if (!flagsValid) {
      throw new Error('Ticket flags do not permit delegation');
    }

    // Step 4: Process the upload
    const hmac = crypto.createHmac('sha256', this.serviceCtx.sessionKey);
    hmac.update(uploadBuffer);
    const integrity = hmac.digest('hex');

    // Step 5: If delegation is permitted, store the delegated ticket
    // for later use in accessing backend services
    if (delegationOk) {
      const s4uTarget = this.extractS4UTarget(uploadBuffer);
      if (s4uTarget && this.checkConstrainedDelegation(s4uTarget)) {
        this.serviceCtx.delegatedTickets.set(ticket.principalName, ticket);
        await this.forwardToBackend(ticket, s4uTarget, uploadBuffer);
        return { success: true, delegatedTo: s4uTarget };
      }
    }

    // Step 6: Write file without delegation
    await fs.promises.writeFile(resolvedDest, uploadBuffer);
    return { success: true };
  }

  private extractS4UTarget(data: Buffer): string | null {
    // Parse upload metadata for S4U2Proxy target
    try {
      const header = data.slice(0, Math.min(512, data.length)).toString('utf8');
      const match = header.match(/X-Target-Service:\s*([^\r\n]+)/);
      return match ? match[1].trim() : null;
    } catch {
      return null;
    }
  }

  private async forwardToBackend(
    ticket: KerberosTicket,
    target: string,
    payload: Buffer
  ): Promise<void> {
    // S4U2Proxy: use the delegated ticket to access the target service
    // on behalf of the user
    const evidence = {
      client: ticket.principalName,
      service: target,
      timestamp: Date.now(),
      payloadHash: crypto.createHash('sha256').update(payload).digest('hex')
    };
    // In production, this would make an actual Kerberos AP-REQ to the target
    console.log(`Delegating ${ticket.principalName} -> ${target}`);
  }
}

export { KerberosAuthProcessor, KerberosTicket, ServiceContext };
